/*removeBuyerMdCmMyGoodsLisList*/

	DELETE FROM ICOMCART                        
	WHERE BUYER     = #{BUYER}                              
		AND USER_ID      = #{USER_ID}                              
		AND USE_FLAG  = #{USE_FLAG}                            
		AND BUYER_ITEM_NO  = #{BUYER_ITEM_NO}                    
		AND CONTRACT_NO  = #{CONTRACT_NO}                        
		AND CONTRACT_SEQ  = #{CONTRACT_SEQ}                    
		AND BYIT_COMORG_CODE  = #{BYIT_COMORG_CODE}
		AND SEQ  = #{SEQ}

mapper.select:
/*selectBuyerMdCmMyRqdtSearchList*/ SELECT A.BUYER_ITEM_NO , A.DESCRIPTION_LOC , A.SPECIFICATION , A.UNIT_MEASURE , A.MAKER_NAME , A.MAKER_CODE , A.ORIGIN_CODE ,( SELECT COD.TEXT1 FROM ICOMCOD1 COD WHERE COD.TYPE='M001' AND COD.CODE = A.ORIGIN_CODE ) ORIGIN_NMAE , 1 RQDT_QTY , CATEGORY_NO AS CATEGORY_CODE , CATEGORY_TEXT AS CATEGORY_NAME
FROM ICOMBYIT A WHERE A.PRODUCT_CLOSE_FLAG IN ('N', 'Y', 'A', 'C') AND A.STATUS != 'D'
AND A.BUYER = #{st_byca_com_code}
AND A.BUYER_ITEM_NO IN
#{item}
UNION ALL SELECT CATLG.CMS_CATLG_ID AS BUYER_ITEM_NO ,CATLG.DESCRIPTION_LOC ,CATLG.SPECIFICATION ,CATLG.ORDER_MEASURE AS UNIT_MEASURE ,CATLG.MAKER_NAME ,CATLG.MAKER_CODE ,CATLG.ORIGIN_CODE ,( SELECT COD.TEXT1 FROM ICOMCOD1 COD WHERE COD.TYPE='M001' AND COD.CODE = CATLG.ORIGIN_CODE ) ORIGIN_NMAE , 1 RQDT_QTY , '' AS CATEGORY_CODE , '' AS CATEGORY_NAME FROM CMSCATLG CATLG WHERE 1=1
AND CATLG.CMS_CATLG_ID IN
#{item}
ORDER BY BUYER_ITEM_NO

/*selectBuyerMdCmGoodsDefaultCateg_v2*/

			SELECT
			DECODE(COUNT(*),0,'N','Y') AS DEFAULT_YN
			FROM ICOMCOD3 COD
			WHERE  COD.TYPE = #{st_type}
			AND COD.BUYER = #{BUYER}
			AND COD.CODE1 = #{USER_ID}
			AND COD.FLAG = 'Y'
			AND COD.CODE2 = #{st_code2}

